class Solution:
    def minOrAfterOperations(self, nums: List[int], k: int) -> int:
        n = len(nums)
        segments = n - k
        memo = {}

        def segment_and(start, end):
            result = nums[start]
            for i in range(start + 1, end + 1):
                result &= nums[i]
            return result

        def dfs(start, segs_left):
            if segs_left == 1:
                return segment_and(start, n - 1)
            if (start, segs_left) in memo:
                return memo[(start, segs_left)]

            res = float('inf')
            for end in range(start, n - segs_left + 1):
                current_and = segment_and(start, end)
                rest_or = dfs(end + 1, segs_left - 1)
                res = min(res, current_and | rest_or)
            memo[(start, segs_left)] = res
            return res

        return dfs(0, segments)"}

